import React, { useState, useEffect } from 'react';
import { adminAPI, apiCall } from '../../services/apiService';
import './PublicVendors.css';

const AllVendors = () => {
  const [vendors, setVendors] = useState([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState('');

  useEffect(() => {
    fetchVendors();
  }, []);

  const fetchVendors = async () => {
    setIsLoading(true);
    setError('');
    const result = await apiCall(adminAPI.getAllVendors);
    if (result.success) {
      setVendors(result.data || []);
    } else {
      setError(result.error);
    }
    setIsLoading(false);
  };

  if (isLoading) {
    return (
      <div className="loading">
        <div className="loading-spinner"></div>
        Loading vendors...
      </div>
    );
  }

  return (
    <div className="public-vendors">
      <div className="page-header">
        <div className="container">
          <h1>All Vendors</h1>
          <p>List of all registered food truck vendors</p>
        </div>
      </div>

      <div className="container">
        {error && <div className="alert alert-error">{error}</div>}

        {vendors.length === 0 ? (
          <div className="no-results">
            <div className="no-results-icon">🚚</div>
            <h3>No Vendors Found</h3>
          </div>
        ) : (
          <div className="vendors-grid">
            {vendors.map(vendor => (
              <VendorCard key={vendor.id} vendor={vendor} />
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

const VendorCard = ({ vendor }) => {
  return (
    <div className="vendor-card">
      <div className="vendor-header">
        <h3 className="vendor-name">{vendor.name}</h3>
        <span className="vendor-region">{vendor.operatingRegion}</span>
      </div>

      <div className="vendor-body">
        <p><strong>Email:</strong> {vendor.email}</p>
        <p><strong>Contact:</strong> {vendor.contactNumber}</p>
        <p><strong>Cuisine:</strong> {vendor.cuisineSpecialties}</p>
        <p><strong>Status:</strong> {vendor.status}</p>
      </div>
    </div>
  );
};

export default AllVendors;
